package vaultor.linked;
import java.nio.file.*;import java.util.*;

public final class LinkedExportTests extends SafetyTests {
    static String export(LinkedPublicationTests.LinkedFixture f,String operation,String kind,Path target)throws Exception{String nonce=UUID.randomUUID().toString();long expires=System.currentTimeMillis()+60000;return f.store.exportSelectedRecovery(OWNER,operation,kind,target,nonce,expires,sign(CONSENT,LinkedStore.exportConsentPayload(OWNER,target,operation,kind,nonce,expires)));}
    static String draft(LinkedPublicationTests.LinkedFixture f)throws Exception{var doc=f.store.openLinked(OWNER,f.rootCap,"guide.md");candidate(f.store,doc,1,"Validated draft");return f.store.recover(OWNER).getFirst().operation();}
    public static void main(String[] args)throws Exception{
        check("new selected derivative exports exact retained validated bytes without source change",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){String operation=draft(f);Path target=f.dir.resolve("copy.md");require(export(f,operation,"local",target).equals("EXPORTED_NEW_FILE"));require(Files.readString(target).equals("Validated draft"));require(Files.readString(f.file).equals("Base"));require(f.store.recover(OWNER).size()==1);}});
        check("selected export never overwrites an original or another existing pathname",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){String operation=draft(f);rejects("ExportCreateNew",()->export(f,operation,"local",f.file));require(Files.readString(f.file).equals("Base"));}});
        check("selected export refuses an existing hardlink without modifying its outside alias",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){String operation=draft(f);Path alias=f.dir.resolve("alias.md");Files.createLink(alias,f.file);rejects("ExportCreateNew",()->export(f,operation,"local",alias));require(Files.readString(alias).equals("Base"));require(Files.readString(f.file).equals("Base"));}});
        check("selected export proof binds choice and target and is single use",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){String operation=draft(f),nonce=UUID.randomUUID().toString();long expires=System.currentTimeMillis()+60000;Path target=f.dir.resolve("copy.md");String signature=sign(CONSENT,LinkedStore.exportConsentPayload(OWNER,target,operation,"local",nonce,expires));rejects("PROOF",()->f.store.exportSelectedRecovery(OWNER,operation,"base",target,nonce,expires,signature));require(f.store.exportSelectedRecovery(OWNER,operation,"local",target,nonce,expires,signature).equals("EXPORTED_NEW_FILE"));rejects("REPLAYED",()->f.store.exportSelectedRecovery(OWNER,operation,"local",target,nonce,expires,signature));}});
        check("selected export refuses a junctioned parent and leaves outside content untouched",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){String operation=draft(f);Path link=Files.createDirectory(f.root.resolve("junction")),outside=Files.createDirectory(f.dir.resolve("outside"));require(external("junction",link,outside.toString())==0);rejects("REPARSE",()->export(f,operation,"local",link.resolve("copy.md")));require(!Files.exists(outside.resolve("copy.md")));}});
        check("rejected visual draft exports separately without minting source Save authority",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){var doc=f.store.openLinked(OWNER,f.rootCap,"guide.md");require(f.store.journalDraft(OWNER,doc.document(),doc.epoch(),1,"Rejected visual draft",null,null)==null);String operation=f.store.recover(OWNER).getFirst().operation();Path target=f.dir.resolve("draft.json");require(export(f,operation,"visual",target).equals("EXPORTED_NEW_FILE"));require(Files.readString(target).equals("Rejected visual draft"));require(Files.readString(f.file).equals("Base"));}});
        Files.writeString(Path.of("native/linked-markdown/evidence/production/export-tests.txt"),String.join("\n",results)+"\npassed="+passed+" failed="+failed+"\n");System.out.println("TOTAL "+passed+" passed; "+failed+" failed");if(failed>0)System.exit(1);
    }
}
